package com.ruoyi.web.controller.shop;
import java.util.*;import java.time.*;import com.alibaba.fastjson2.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.Lazy;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static com.ruoyi.web.controller.shop.ShopService.*;
@Service public class ShopGrades {
 @Autowired @Lazy ShopService s;
 public JSONObject settings(){JSONObject c=JSON.parseObject(str(s.one("select content from shop_config where config_key='grades'").get("content")));c.put("retailPriceMode","fixed");c.put("discounts",JSONArray.of(10000,10000,10000));c.putIfAbsent("purchasePriority","agreement_first");if(!c.containsKey("purchaseNames"))c.put("purchaseNames",new JSONArray(c.getJSONArray("names")));if(!c.containsKey("purchaseThresholds"))c.put("purchaseThresholds",JSONArray.of(0,c.getLongValue("silver"),c.getLongValue("gold")));return c;}
 public long tier(String scope,long owner){List<Map<String,Object>> r=s.jdbc().queryForList("select tier from shop_grade where scope=? and owner_id=?",scope,owner);return r.isEmpty()?0:number(r.get(0).get("tier"));}
 private long company(long certified){List<Map<String,Object>> r=s.jdbc().queryForList("select id from shop_company where certified_member_id=?",certified);return r.isEmpty()?0:number(r.get(0).get("id"));}
 private boolean active(Map<String,Object> r){long now=System.currentTimeMillis();return (Boolean.TRUE.equals(r.get("enabled"))||"1".equals(str(r.get("enabled"))))&&(r.get("starts_at")==null||timestamp(r.get("starts_at")).getTime()<=now)&&(r.get("ends_at")==null||timestamp(r.get("ends_at")).getTime()>now);}
 public long retail(Map<String,Object> p,long uid){return number(p.get("price"));}
 public Map<String,Object> purchase(Map<String,Object> p,long certified,long qty){long cid=company(certified);return calculate(p,certified,qty,s.jdbc().queryForList("select * from shop_purchase_rule where product_id=?",p.get("id")),s.jdbc().queryForList("select * from shop_company_price where company_id=? and product_id=?",cid,p.get("id")),s.jdbc().queryForList("select price from shop_grade_price where product_id=? and tier=?",p.get("id"),tier("B",cid)),settings().getString("purchasePriority"));}
 private Map<String,Object> calculate(Map<String,Object> p,long certified,long qty,List<Map<String,Object>> rules,List<Map<String,Object>> agreements,List<Map<String,Object>> grades,String priority){long price=number(p.get("wholesale")),minimum=number(p.get("pack")),multiple=number(p.get("pack"));String basis="采购基础价";if(!rules.isEmpty()){minimum=number(rules.get(0).get("min_qty"));multiple=number(rules.get(0).get("multiple_qty"));}boolean agreed=false;JSONObject legacy=JSON.parseObject(str(p.get("pricing_json")).isEmpty()?"{}":str(p.get("pricing_json")));if(!agreements.isEmpty()&&active(agreements.get(0))){Map<String,Object> a=agreements.get(0);price=number(a.get("price"));minimum=number(a.get("min_qty"));multiple=number(a.get("multiple_qty"));agreed=true;basis="企业协议价";}else if(agreements.isEmpty()){JSONArray old=legacy.getJSONArray("agreements");if(old!=null)for(Object obj:old){JSONObject a=(JSONObject)obj;if(a.getLongValue("memberId")==certified){price=a.getLongValue("price");agreed=true;basis="企业协议价";break;}}}
 if(!agreed||"lowest".equals(priority)){long best=agreed?price:Long.MAX_VALUE;if(!grades.isEmpty()&&number(grades.get(0).get("price"))<best){best=number(grades.get(0).get("price"));basis="采购等级价";agreed=false;}JSONArray steps=legacy.getJSONArray("tiers");if(steps!=null)for(Object obj:steps){JSONObject t=(JSONObject)obj;if(qty>=t.getLongValue("quantity")&&t.getLongValue("price")<best){best=t.getLongValue("price");basis="采购阶梯价";agreed=false;}}if(best!=Long.MAX_VALUE)price=best;}
 Map<String,Object> out=new HashMap<>();out.put("price",price);out.put("minimum",minimum);out.put("multiple",multiple);out.put("basis",basis);out.put("agreement",agreed);out.put("gradePrice",grades.isEmpty()?null:grades.get(0).get("price"));return out;}
 private List<Map<String,Object>> matching(List<Map<String,Object>> rows,long id){List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> r:rows)if(number(r.get("product_id"))==id)out.add(r);return out;}
 public List<Map<String,Object>> catalog(long uid,long certified){List<Map<String,Object>> products=s.products();s.catalogStock(products);JSONObject config=settings();long cid=certified>0?company(certified):0;List<Map<String,Object>> quantities=certified>0?s.jdbc().queryForList("select * from shop_purchase_rule"):Collections.emptyList(),agreements=certified>0?s.jdbc().queryForList("select * from shop_company_price where company_id=?",cid):Collections.emptyList(),prices=certified>0?s.jdbc().queryForList("select * from shop_grade_price where tier=?",tier("B",cid)):Collections.emptyList();for(Map<String,Object> p:products){p.put("standardPrice",p.get("price"));p.put("price",retail(p,uid));if(certified>0){long id=number(p.get("id"));String priority=config.getString("purchasePriority");Map<String,Object> info=calculate(p,certified,1,matching(quantities,id),matching(agreements,id),matching(prices,id),priority);JSONObject legacy=JSON.parseObject(str(p.get("pricing_json")).isEmpty()?"{}":str(p.get("pricing_json")));p.put("wholesale",info.get("price"));p.put("priceBasis",info.get("basis"));p.put("minimum",info.get("minimum"));p.put("pack",info.get("multiple"));p.put("purchasePriority",priority);p.put("agreementPrice",info.get("agreement"));p.put("gradePrice",info.get("gradePrice"));p.put("tiers",Boolean.TRUE.equals(info.get("agreement"))&&!"lowest".equals(priority)?new JSONArray():legacy.getJSONArray("tiers"));}else p.remove("wholesale");p.remove("pricing_json");}return products;}
 public void validate(Map<String,Object> p,long certified,long qty){Map<String,Object> r=purchase(p,certified,qty);check(qty>=number(r.get("minimum"))&&qty%number(r.get("multiple"))==0,str(p.get("name"))+"至少采购"+r.get("minimum")+"件，每次按"+r.get("multiple")+"件增加");}
 private String performanceSource(){return " and o.status='completed' and o.paid_at>=date_sub(now(),interval 365 day)"+(s.isDemo()?"":" and o.is_test=0 and exists(select 1 from shop_payment paid join shop_member buyer on buyer.id=o.member_id where paid.order_id=o.id and paid.mode<>'simulation' and buyer.is_test=0)");}
 public long performance(String scope,long owner){return s.jdbc().queryForObject("select coalesce(sum(o.amount-o.shipping_amount-o.refunded_amount+o.refunded_shipping_amount),0) from shop_order o where o.channel=? and o."+("B".equals(scope)?"company_id":"member_id")+"=?"+performanceSource(),Long.class,scope,owner);}
 @Transactional public void recalculate(String who){JSONObject c=settings();for(String scope:Arrays.asList("C","B")){if(!c.getBooleanValue("auto"+scope))continue;if("B".equals(scope)){recalculatePurchase(c,who);continue;}String owners="B".equals(scope)?"shop_company":"shop_member",field="B".equals(scope)?"company_id":"member_id";List<Map<String,Object>> rows=s.jdbc().queryForList("select m.id owner_id,coalesce(g.tier,0) old_tier,case when coalesce(p.amount,0)>=? then 2 when coalesce(p.amount,0)>=? then 1 else 0 end new_tier from "+owners+" m left join (select o."+field+" owner_id,sum(o.amount-o.shipping_amount-o.refunded_amount+o.refunded_shipping_amount) amount from shop_order o where o.channel=?"+performanceSource()+" group by o."+field+") p on p.owner_id=m.id left join shop_grade g on g.scope=? and g.owner_id=m.id"+(!s.isDemo()?" where m.is_test=0":""),c.getLongValue("gold"),c.getLongValue("silver"),scope,scope);List<Object[]> changes=new ArrayList<>(),logs=new ArrayList<>();for(Map<String,Object> row:rows)if(number(row.get("old_tier"))!=number(row.get("new_tier"))){changes.add(new Object[]{scope,row.get("owner_id"),row.get("new_tier")});logs.add(new Object[]{row.get("owner_id"),scope+"自动等级从"+row.get("old_tier")+"调整为"+row.get("new_tier")+"，依据近365天完成订单净额",who});}if(!changes.isEmpty()){s.jdbc().batchUpdate("insert into shop_grade(scope,owner_id,tier) values(?,?,?) on duplicate key update tier=values(tier)",changes);s.jdbc().batchUpdate("insert into shop_event(object_type,object_id,action,operator_name) values('grade',?,?,?)",logs);}}}
 private void recalculatePurchase(JSONObject c,String who){JSONArray thresholds=c.getJSONArray("purchaseThresholds");List<Map<String,Object>> rows=s.jdbc().queryForList("select m.id owner_id,coalesce(g.tier,0) old_tier,coalesce(p.amount,0) amount from shop_company m left join (select o.company_id owner_id,sum(o.amount-o.shipping_amount-o.refunded_amount+o.refunded_shipping_amount) amount from shop_order o where o.channel='B'"+performanceSource()+" group by o.company_id) p on p.owner_id=m.id left join shop_grade g on g.scope='B' and g.owner_id=m.id"+(!s.isDemo()?" where exists(select 1 from shop_member owner where owner.id=m.certified_member_id and owner.is_test=0)":""));List<Object[]> changes=new ArrayList<>(),logs=new ArrayList<>();for(Map<String,Object> row:rows){int next=0;for(int i=1;i<thresholds.size();i++)if(number(row.get("amount"))>=thresholds.getLongValue(i))next=i;if(number(row.get("old_tier"))!=next){changes.add(new Object[]{"B",row.get("owner_id"),next});logs.add(new Object[]{row.get("owner_id"),"B自动等级从"+row.get("old_tier")+"调整为"+next+"，依据近365天完成采购净额",who});}}if(!changes.isEmpty()){s.jdbc().batchUpdate("insert into shop_grade(scope,owner_id,tier) values(?,?,?) on duplicate key update tier=values(tier)",changes);s.jdbc().batchUpdate("insert into shop_event(object_type,object_id,action,operator_name) values('grade',?,?,?)",logs);}}
 @Transactional public void assign(JSONObject b,String who){String scope=b.getString("scope");check(Arrays.asList("C","B").contains(scope),"请选择会员或采购商");long id=integer(b.get("id"),1,Long.MAX_VALUE,"客户不正确"),tier=integer(b.get("tier"),0,"B".equals(scope)?settings().getJSONArray("purchaseNames").size()-1:2,"请选择等级");s.one("select id from "+("B".equals(scope)?"shop_company":"shop_member")+" where id=? for update",id);String reason=str(b.get("reason")).trim();check(reason.length()>=2&&reason.length()<=300,"请填写调整原因");s.jdbc().update("insert into shop_grade(scope,owner_id,tier) values(?,?,?) on duplicate key update tier=values(tier)",scope,id,tier);s.event("grade",id,scope+"等级调整为"+tier+"；"+reason,who);}
 @Transactional public void save(JSONObject b,String who){JSONArray names=b.getJSONArray("names"),discounts=b.getJSONArray("discounts");check(names!=null&&names.size()==3&&discounts!=null&&discounts.size()==3,"请填写三个等级及权益");for(Object n:names)check(str(n).trim().length()>0&&str(n).length()<=20,"等级名称为1至20字");for(Object d:discounts)integer(d,1,10000,"折扣比例为0.01%至100%");JSONObject previous=settings();JSONArray purchaseNames=b.containsKey("purchaseNames")?b.getJSONArray("purchaseNames"):previous.getJSONArray("purchaseNames"),thresholds=b.containsKey("purchaseThresholds")?b.getJSONArray("purchaseThresholds"):previous.getJSONArray("purchaseThresholds");check(purchaseNames!=null&&purchaseNames.size()>=1&&purchaseNames.size()<=20&&thresholds!=null&&thresholds.size()==purchaseNames.size(),"采购等级为1至20档，每档须设置升级门槛");Set<String> unique=new HashSet<>();long last=-1;for(int i=0;i<purchaseNames.size();i++){String name=str(purchaseNames.get(i)).trim();check(!name.isEmpty()&&name.length()<=20&&unique.add(name),"采购等级名称为1至20字且不能重复");purchaseNames.set(i,name);long threshold=integer(thresholds.get(i),0,1000000000,"采购门槛须为非负整数分");check(i==0?threshold==0:threshold>last,"基础等级门槛为0，其余门槛须依次递增");last=threshold;}s.one("select config_key from shop_config where config_key='grades' for update");check(s.jdbc().queryForObject("select count(*) from shop_grade where scope='B' and tier>=?",Long.class,purchaseNames.size())==0&&s.jdbc().queryForObject("select count(*) from shop_grade_price where tier>=?",Long.class,purchaseNames.size())==0,"待移除等级仍有采购客户或商品价格，请先调整客户并取消对应价格");JSONObject c=new JSONObject();c.put("purchaseNames",purchaseNames);c.put("purchaseThresholds",thresholds);String priority=str(b.getOrDefault("purchasePriority",settings().get("purchasePriority")));check(Arrays.asList("agreement_first","lowest").contains(priority),"请选择采购价格优先规则");c.put("purchasePriority",priority);c.put("names",names);c.put("retailPriceMode","fixed");c.put("discounts",JSONArray.of(10000,10000,10000));c.put("autoC",b.getBooleanValue("autoC"));c.put("autoB",b.getBooleanValue("autoB"));c.put("silver",integer(b.get("silver"),1,1000000000,"门槛应为正整数分"));c.put("gold",integer(b.get("gold"),1,1000000000,"门槛应为正整数分"));check(c.getLongValue("gold")>c.getLongValue("silver"),"金卡门槛须高于银卡");s.jdbc().update("update shop_config set content=? where config_key='grades'",c.toJSONString());s.event("grade",0,"保存等级权益，仅新报价生效",who);}
 private java.sql.Timestamp date(Object v){String text=str(v);if(text.isEmpty())return null;try{return java.sql.Timestamp.valueOf(LocalDateTime.parse(text.replace(" ","T")));}catch(Exception e){throw new IllegalArgumentException("有效期格式不正确");}}
 @Transactional public void pricing(JSONObject b,String who){long product=integer(b.get("productId"),1,Long.MAX_VALUE,"请选择商品");s.one("select id from shop_product where id=? for update",product);String type=b.getString("type");if("quantity".equals(type)){long min=integer(b.get("minimum"),1,10000,"最少数量为1至10000"),multiple=integer(b.get("multiple"),1,10000,"倍数为1至10000");check(min%multiple==0,"最少数量须为采购倍数的整数倍");s.jdbc().update("insert into shop_purchase_rule values(?,?,?) on duplicate key update min_qty=values(min_qty),multiple_qty=values(multiple_qty)",product,min,multiple);}else if("grade".equals(type)){long tier=integer(b.get("tier"),0,settings().getJSONArray("purchaseNames").size()-1,"请选择采购等级");if(b.getBooleanValue("remove"))s.jdbc().update("delete from shop_grade_price where product_id=? and tier=?",product,tier);else s.jdbc().update("insert into shop_grade_price values(?,?,?) on duplicate key update price=values(price)",product,tier,integer(b.get("price"),1,100000000,"价格应为正整数分"));}else{check("company".equals(type),"请选择价格设置类型");long company=integer(b.get("companyId"),1,Long.MAX_VALUE,"请选择企业");s.one("select id from shop_company where id=?",company);java.sql.Timestamp start=date(b.get("start")),end=date(b.get("end"));check(start==null||end==null||end.after(start),"结束时间须晚于开始时间");long min=integer(b.get("minimum"),1,10000,"最少数量不正确"),multiple=integer(b.get("multiple"),1,10000,"采购倍数不正确");check(min%multiple==0,"最少数量须为采购倍数的整数倍");s.jdbc().update("insert into shop_company_price values(?,?,?,?,?,?,?,?) on duplicate key update price=values(price),min_qty=values(min_qty),multiple_qty=values(multiple_qty),starts_at=values(starts_at),ends_at=values(ends_at),enabled=values(enabled)",company,product,integer(b.get("price"),1,100000000,"价格应为正整数分"),min,multiple,start,end,b.getBooleanValue("enabled"));}s.event("product",product,"调整采购价格或起订，新报价生效",who);}
 public Map<String,Object> summary(long uid){Map<String,Object> r=new HashMap<>();JSONObject c=settings();r.put("settings",c);r.put("tier",tier("C",uid));r.put("performance",performance("C",uid));List<Map<String,Object>> companies=s.jdbc().queryForList("select company_id from shop_company_member where member_id=? and enabled=1",uid);if(!companies.isEmpty()){long id=number(companies.get(0).get("company_id"));r.put("companyTier",tier("B",id));r.put("companyPerformance",performance("B",id));}return r;}
}
